using ReviveOS.CloudEngine;
using Xunit;
public class JobTests {
 [Fact] public async Task PythonJobProducesVerifiedArtifactAndFailureIsRecorded(){var root=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString());Directory.CreateDirectory(root);try{var input=Path.Combine(root,"source.py");await File.WriteAllTextAsync(input,"from pathlib import Path\nPath('result.json').write_text('{\"ok\":true}')\n");var runner=new JobRunner(Path.Combine(root,"jobs"));var result=await runner.Run("python",input,null,false);Assert.Equal("completed",result.State);Assert.True(File.Exists(result.Result));Assert.True(File.Exists(Path.Combine(root,"jobs",result.Id,"result.sha256.json")));await File.WriteAllTextAsync(input,"raise RuntimeError('expected test failure')\n");await Assert.ThrowsAsync<IOException>(()=>runner.Run("python",input,null,false));Assert.Contains(runner.History(),x=>x.State=="failed");}finally{Directory.Delete(root,true);}}
 [Fact] public async Task RemoteRequiresExplicitUploadConsent(){var runner=new JobRunner("unused");await Assert.ThrowsAsync<ArgumentException>(()=>runner.Run("python","none.py","host",false));await Assert.ThrowsAsync<ArgumentException>(()=>runner.Run("python","none.py","host;bad",true));}
 [Fact] public void InterruptedSessionsNeverPretendToComplete(){var root=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString());try{ReviveOS.Core.State.Save(Path.Combine(root,"id","job.json"),new JobRecord("id","REMOTE","python","source","running",DateTime.UtcNow,null,null,"host",".reviveos/jobs/id"));var runner=new JobRunner(root);runner.RecoverInterrupted();Assert.Equal("interrupted",Assert.Single(runner.History()).State);}finally{Directory.Delete(root,true);}}
}
